 "content": "from collections import Counter


def _components(grid, background):
    h, w = len(grid), len(grid[0])
    seen, result = set(), []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == background or (r, c) in seen:
                continue
            seen.add((r, c))
            stack, cells = [(r, c)], []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w
                            and grid[ny][nx] != background
                            and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            result.append(cells)
    return result


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    components = _components(grid, background)
    template = None
    for comp in components:
        if len(comp) != 3:
            continue
        rs = [r for r, c in comp]
        cs = [c for r, c in comp]
        if len(set(rs)) == 1 or len(set(cs)) == 1:
            template = comp
            break
    if template is None:
        return [row[:] for row in grid]
    template = sorted(template)
    if len({r for r, c in template}) == 1:
        template.sort(key=lambda p: p[1])
    else:
        template.sort(key=lambda p: p[0])
    motif = [grid[r][c] for r, c in template]
    mid_r, mid_c = template[1]
    out = [row[:] for row in grid]
    template_cells = set(template)
    markers = [comp[0] for comp in components if len(comp) == 1 and comp[0] not in template_cells]
    for mr, mc in markers:
        for i, value in enumerate(motif):
            rr = mr + template[i][0] - mid_r
            cc = mc + template[i][1] - mid_c
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = value
    return out
